if (!btn1 || !btn1.classList.contains('ai4a11y-plain-btn')) return false;
if (p1.hasAttribute('hidden')) return false;
if (btn1.textContent.trim() !== 'Plain language') return false;

btn1.click();
await new Promise(r => setTimeout(r, 60));

