const repBox = p1.parentElement.querySelector('[data-ai4a11y-replaced]');
if (!repBox || repBox.hasAttribute('hidden')) return false;
if (btn1.textContent.trim() !== 'Show original') return false;

btn1.click();
await new Promise(r => setTimeout(r, 60));

if (p1.hasAttribute('hidden')) return false;
if (!repBox.hasAttribute('hidden')) return false;
if (btn1.textContent.trim() !== 'Plain language') return false;

