const calls = window.__verifyAiCalls || [];
const p1Call = calls.find(c => c.input && c.input.includes('Metropolitan Community Health'));
const p2Call = calls.find(c => c.input && c.input.includes('Subsidized clinical remuneration'));
const p3Call = calls.find(c => c.input && c.input.includes('specialized pharmaceutical dispensation'));

if (!p1Call || !p2Call || !p3Call) return false;

const hasReadingLevel = Boolean(p3Call.options && p3Call.options.readingLevel);
const k1 = p1Call.options?.keep || [];
const k2 = p2Call.options?.keep || [];
const k3 = p3Call.options?.keep || [];

const hasTime = k1.includes('4:30 PM') && !k1.includes('30 PM');
const hasPercent = k2.includes('250%');
const hasMedicarePartB = k2.includes('Medicare Part B');
const hasCurrency = k3.includes('$50,000');
const hasJan15 = k3.includes('Jan. 15, 2024');
const has15Jan = k3.includes('15 Jan. 2024');

return hasReadingLevel && hasTime && hasPercent && hasMedicarePartB && hasCurrency && hasJan15 && has15Jan;

const adapter = globalThis.__ai4a11yRuntime?.adapters?.preview?.adapter;
if (!adapter || !adapter.s || adapter.s.ended) return true;
return adapter.enable() === false;

